choose.when:
SELECT  FROM link_attempt
WHERE entity = #{entity}::char(1) AND subject_id IN
#{i}

mapper.select:
SELECT  FROM link_attempt
WHERE entity = #{entity}::char(1) AND next_try IS NOT NULL AND next_try <= #{now}
ORDER BY next_try, subject_id, lookup LIMIT #{limit}

choose.when:
SELECT subject_id FROM (
  SELECT DISTINCT a.subject_id FROM link_attempt a
  WHERE a.entity = #{entity}::char(1) AND a.next_try IS NOT NULL AND a.next_try <= #{now}
    AND a.lookup IN #{l}
    AND (

      EXISTS (SELECT 1 FROM work w WHERE w.id = a.subject_id AND w.state IN ('INDEXED','NOTIFIED'))
      EXISTS (SELECT 1 FROM source c WHERE c.id = a.subject_id AND c.publication_status IS DISTINCT FROM 'CEASED')
    )
) d ORDER BY subject_id LIMIT #{limit}
